"""Inline vector studies for user selection; no exported image files."""
from html import escape

ART = [
    ('A', '容器 · 监测', '沿用容器意象，加入一条轻量监测曲线。', '''<g fill="white" opacity=".96"><rect x="126" y="130" width="74" height="74" rx="14"/><rect x="219" y="130" width="74" height="74" rx="14"/><rect x="312" y="130" width="74" height="74" rx="14"/><rect x="126" y="223" width="74" height="74" rx="14"/><rect x="219" y="223" width="74" height="74" rx="14"/><rect x="312" y="223" width="74" height="74" rx="14"/></g><path d="M98 330h316" fill="none" stroke="white" stroke-width="24" stroke-linecap="round" opacity=".82"/><path d="M116 374h90l25-35 35 62 29-45 21 18h80" fill="none" stroke="white" stroke-width="19" stroke-linecap="round" stroke-linejoin="round"/>'''),
    ('B', '方盒 · 脉冲', '单个立体容器，正面嵌入心跳波形。', '''<path d="M256 100 402 185v157l-146 84-146-84V185Z" fill="white" fill-opacity=".13" stroke="white" stroke-width="19" stroke-linejoin="round"/><path d="m110 185 146 84 146-84M256 269v157" fill="none" stroke="white" stroke-opacity=".7" stroke-width="16" stroke-linejoin="round"/><path d="m140 293 32 19 18-33 28 72 19-9" fill="none" stroke="white" stroke-width="17" stroke-linecap="round" stroke-linejoin="round"/><path d="m285 316 31-18 20 20 22-60 23 1" fill="none" stroke="white" stroke-width="17" stroke-linecap="round" stroke-linejoin="round"/>'''),
    ('C', '雷达 · 守望', '圆形监控意象，三点代表运行中的服务。', '''<circle cx="256" cy="256" r="150" fill="none" stroke="white" stroke-width="18" opacity=".95"/><circle cx="256" cy="256" r="95" fill="none" stroke="white" stroke-width="13" opacity=".35"/><path d="M256 106v150l-106 106" fill="none" stroke="white" stroke-width="18" stroke-linecap="round" stroke-linejoin="round"/><path d="M256 106a150 150 0 0 1 150 150H256Z" fill="white" opacity=".12"/><circle cx="256" cy="256" r="23" fill="white"/><circle cx="333" cy="206" r="20" fill="white"/><circle cx="204" cy="333" r="18" fill="white"/>'''),
    ('D', '字母 · DM', '以 Docker Monitor 首字母构成简洁标记。', '''<path d="M108 162h40c63 0 88 38 88 94s-25 94-88 94h-40Z" fill="none" stroke="white" stroke-width="29" stroke-linejoin="round"/><path d="M278 350V162l57 91 57-91v188" fill="none" stroke="white" stroke-width="29" stroke-linejoin="round" stroke-linecap="round"/>'''),
]


def svg(code, drawing):
    return f'''<svg viewBox="0 0 512 512" xmlns="http://www.w3.org/2000/svg" aria-label="方案 {code}" role="img"><defs><linearGradient id="bg{code}" x1="0" y1="0" x2=".85" y2="1"><stop stop-color="#53a4ff"/><stop offset=".5" stop-color="#147be9"/><stop offset="1" stop-color="#0753be"/></linearGradient><linearGradient id="shine{code}" x2="0" y2="1"><stop stop-color="white" stop-opacity=".22"/><stop offset="1" stop-color="white" stop-opacity="0"/></linearGradient></defs><rect x="6" y="6" width="500" height="500" rx="114" fill="url(#bg{code})"/><rect x="7" y="7" width="498" height="498" rx="113" fill="none" stroke="white" stroke-opacity=".25" stroke-width="3"/><path d="M120 8h272c62 0 112 49 112 112v110C362 169 152 150 8 239V120C8 58 58 8 120 8Z" fill="url(#shine{code})"/>{drawing}</svg>'''


def page():
    cards = []
    for code,title,desc,drawing in ART:
        mark=svg(code,drawing)
        cards.append(f'''<article data-option="{code}"><div class="option-top"><span class="code">{code}</span><span class="selected-label">已选</span></div><div class="hero">{mark}</div><h2>{title}</h2><p>{desc}</p><div class="sizes"><span class="size16">{mark}<small>16</small></span><span class="size32">{mark}<small>32</small></span><span class="size48">{mark}<small>48</small></span></div><div class="nav">{mark}<div><strong>Docker Monitor</strong><small>容器运行监控</small></div><i></i></div><div class="bark">{mark}<div><small>Docker Monitor · 现在</small><strong>发现镜像更新</strong><span>HaBridge 有新镜像可用</span></div></div><button type="button" data-choose="{code}">选择 {code}</button></article>''')
    return '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Docker Monitor · 图标选择</title><style>
:root{color-scheme:light dark;--bg:#f5f6f8;--card:#fff;--text:#24272e;--sub:#80838b;--line:#e8eaef;--soft:#f7f8fa;--blue:#0071e3}
@media(prefers-color-scheme:dark){:root{--bg:#111318;--card:#1c1f26;--text:#eef0f5;--sub:#9297a3;--line:#30343e;--soft:#252932}}
html[data-theme=light]{color-scheme:light;--bg:#f5f6f8;--card:#fff;--text:#24272e;--sub:#80838b;--line:#e8eaef;--soft:#f7f8fa}
html[data-theme=dark]{color-scheme:dark;--bg:#111318;--card:#1c1f26;--text:#eef0f5;--sub:#9297a3;--line:#30343e;--soft:#252932}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1440px;margin:auto;padding:48px 40px 32px}header{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:34px}header span{font-size:12px;letter-spacing:2px;color:var(--blue)}h1{font-size:32px;letter-spacing:-1px;margin:10px 0}header p{font-size:14px;color:var(--sub);margin:8px 0;line-height:1.7}button{font:inherit;cursor:pointer;border:1px solid var(--line);border-radius:11px;background:var(--soft);color:var(--text);transition:transform .2s,background .2s}button:active{transform:scale(.97)}header button{padding:11px 16px}section{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px}article{background:var(--card);border:1px solid var(--line);border-radius:24px;padding:22px;box-shadow:0 5px 16px #00000003;transition:box-shadow .25s,border-color .25s}article.selected{border-color:var(--blue);box-shadow:0 0 0 3px #0071e312}.option-top{display:flex;justify-content:space-between;align-items:center}.code{color:var(--sub);font-size:12px}.selected-label{visibility:hidden;font-size:12px;color:var(--blue)}.selected .selected-label{visibility:visible}.hero{height:190px;display:flex;align-items:center;justify-content:center}.hero svg{width:136px;height:136px;filter:drop-shadow(0 12px 12px #0753be20)}h2{font-size:17px;margin:8px 0 10px}article p{font-size:12px;line-height:1.8;color:var(--sub);margin:0;min-height:44px}.sizes{height:100px;display:flex;align-items:center;justify-content:center;gap:34px;border-bottom:1px solid var(--line)}.sizes>span{display:flex;align-items:center;flex-direction:column;gap:9px}.sizes small{font-size:10px;color:var(--sub)}.size16 svg{width:16px;height:16px}.size32 svg{width:32px;height:32px}.size48 svg{width:48px;height:48px}.nav{display:flex;gap:10px;align-items:center;height:78px}.nav svg{width:34px;height:34px;flex-shrink:0}.nav strong{font-size:12px}.nav small{display:block;font-size:9px;color:var(--sub);margin-top:3px}.nav i{background:#4b9670;width:5px;height:5px;border-radius:50%;margin-left:auto}.bark{display:flex;gap:10px;padding:14px 10px;background:var(--soft);border-radius:14px;align-items:center}.bark svg{width:33px;height:33px;flex-shrink:0}.bark small{font-size:9px;color:var(--sub)}.bark strong{display:block;font-size:11px;margin:5px 0}.bark span{font-size:10px;color:var(--sub)}article button{width:100%;padding:12px;margin-top:22px;color:var(--blue);background:#0071e308}footer{font-size:12px;color:var(--sub);text-align:center;margin-top:28px;line-height:1.8}@media(max-width:1000px){section{grid-template-columns:repeat(2,1fr)}}@media(max-width:580px){main{padding:26px 18px}section{grid-template-columns:1fr}header{gap:16px}h1{font-size:26px}.hero{height:170px}}
</style></head><body><main><header><div><span>DOCKER MONITOR</span><h1>挑一个，你喜欢的图标。</h1><p>同一套蓝色，四种轮廓。大图、标签栏与 Bark 通知一起看。</p></div><button id="theme">切换明暗</button></header><section>''' + ''.join(cards) + '''</section><footer id="result">点击选择后，在聊天里告诉我 A / B / C / D；选定前不替换正式图标。<br>这些是本地 SVG 方案，没有导出图片，也没有更新群晖。</footer></main><script>document.querySelectorAll('[data-choose]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('article').forEach(c=>c.classList.toggle('selected',c.dataset.option===b.dataset.choose));document.querySelector('#result').textContent='已预选 '+b.dataset.choose+' · 在聊天里告诉我你的选择，可继续调整细节。'}));document.querySelector('#theme').addEventListener('click',()=>{const root=document.documentElement,current=root.dataset.theme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');root.dataset.theme=current==='light'?'dark':'light'});</script></body></html>'''
